using namespace std;

typedef pair<int, int> P;

vector<P> e[100000];
vector<P> ge[100000];
vector<P> te[100000];
int d[100000], bfr[100000], depth[100000];
int par[20][100000], cos[20][100000];
int n, m, k, q;

priority_queue<P, vector<P>, greater<P>> que;

void dykstra() {
    while (!que.empty()) {
        int v = que.top().second;
        int dist = que.top().first;
        que.pop();
        if (dist > d[v]) continue;
        for (const auto& edge : e[v]) {
            int u = edge.to;
            int c = edge.cost;
            if (d[u] > d[v] + c) {
                d[u] = d[v] + c;
                que.emplace(d[u], u);
            }
        }
    }
}

void mt() {
    fill(d, d + n, INF);
    fill(bfr, bfr + n, -1);
    d[0] = 0;
    que.emplace(0, 0);
    while (!que.empty()) {
        int v = que.top().second;
        int dist = que.top().first;
        que.pop();
        if (dist > d[v]) continue;
        if (bfr[v] != -1) {
            te[v].emplace_back(bfr[v], -d[v]);
            te[bfr[v]].emplace_back(v, -d[v]);
        }
        for (const auto& edge : ge[v]) {
            int u = edge.to;
            int c = edge.cost;
            if (d[u] > c) {
                d[u] = c;
                bfr[u] = v;
                que.emplace(d[u], u);
            }
        }
    }
}

void dfs(int v, int p, int d) {
    depth[v] = d;
    for (const auto& edge : te[v]) {
        if (edge.to == p) continue;
        par[0][edge.to] = v;
        cos[0][edge.to] = edge.cost;
        dfs(edge.to, v, d + 1);
    }
}

int lca(int a, int b) {
    if (depth[a] < depth[b]) swap(a, b);
    int ans = INF;
    int diff = depth[a] - depth[b];
    for (int i = 0; i < 20; i++) {
        if (diff >> i & 1) {
            ans = min(ans, cos[i][a]);
            a = par[i][a];
        }
    }
    if (a == b) return ans;
    for (int i = 19; i >= 0; i--) {
        if (par[i][a] != par[i][b]) {
            ans = min(ans, cos[i][a]);
            ans = min(ans, cos[i][b]);
            a = par[i][a];
            b = par[i][b];
        }
    }
    ans = min(ans, cos[0][a]);
    ans = min(ans, cos[0][b]);
    return ans;
}

